final class IdentityHash {
    static String of(String operation, String resource, String operator, String expectedVersion, List<String> params) {
        StringBuilder sb = new StringBuilder();
        append(sb, operation); append(sb, resource); append(sb, operator); append(sb, expectedVersion);
        for (String p : params) append(sb, p);
        return sha256(sb.toString());
    }
    private static void append(StringBuilder sb, String v) {
        if (v == null) { sb.append("-1:"); } else { sb.append(v.length()).append(':').append(v).append(';'); }
    }
    static String decimal(String raw) // normalize decimal by value
}
