        // t0 不小于 t1（两端颠倒）→ 422
        mvc.perform(post("/api/measurements/drift").contentType(MediaType.APPLICATION_JSON)
                        .content(driftJson("B-1", "INS-D", "2026-06-01T10:30:00Z",
