                        .content(driftJson("P-2", "INS-D", "2026-06-01T10:30:00.0001Z",
                                "1", "0", "9", "alice", a0, a1)))
                .andExpect(status().isBadRequest());

        Integer count = jdbc.queryForObject("SELECT COUNT(*) FROM measurement", Integer.class);
        assertEquals(0, count, "超精度输入不得产生测量记录");
